scene.add(new T.HemisphereLight('#fff7e7','#9b9d90',2));const key=new T.DirectionalLight('#fff7e9',3);key.position.set(-3,7,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-4,right:4,top:5,bottom:-4});key.shadow.normalBias=.018;key.shadow.radius=5;scene.add(key);const fill=new T.DirectionalLight('#e8eef2',1.4);fill.position.set(4,3,-4);scene.add(fill);
