let on=false,chosen='chalk',hoverX=0,hoverY=0,last=performance.now(),dragging=false,dragMoved=false,dragStart=0,dragStartY=0,dragBase=0,dragBaseY=0,rotationBase=0,tiltBase=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const finishes={chalk:{color:new T.Color('#ded5c1'),metal:.22,rough:.32},bronze:{color:new T.Color('#a57847'),metal:.88,rough:.26}};
function toggle(){on=!on;button.textContent=on?'Light on ↗':'Light off ↗';button.setAttribute('aria-pressed',on);stage.setAttribute('aria-pressed',on)}button.onclick=toggle;stage.addEventListener('click',()=>{if(!dragMoved)toggle()});stage.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}});
