stage.style.touchAction='none';
stage.addEventListener('pointerdown',e=>{dragging=true;dragMoved=false;dragStart=e.clientX;dragStartY=e.clientY;dragBase=hoverX;dragBaseY=hoverY;stage.setPointerCapture(e.pointerId);stage.style.cursor='grabbing'});
