function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;const t=reduced?1:1-Math.exp(-dt*4),f=finishes[chosen];lamp.rotation.y=T.MathUtils.lerp(lamp.rotation.y,hoverX,t);lamp.rotation.x=T.MathUtils.lerp(lamp.rotation.x,hoverY,t);finish.color.lerp(f.color,t);finish.metalness=T.MathUtils.lerp(finish.metalness,f.metal,t);finish.roughness=T.MathUtils.lerp(finish.roughness,f.rough,t);diffuserMat.emissiveIntensity=T.MathUtils.lerp(diffuserMat.emissiveIntensity,on?2.5:0,t);glow.intensity=T.MathUtils.lerp(glow.intensity,on?10:0,t);poolMat.opacity=T.MathUtils.lerp(poolMat.opacity,on?.65:0,t);indicatorMat.color.lerp(new T.Color(on?'#e6c48b':'#727865'),t);renderer.render(scene,camera)}requestAnimationFrame(animate);
